function:acquire(p_environment uuid, p_d.definition:
CREATE OR REPLACE FUNCTION organization_witness.acquire(p_environment uuid, p_deployment uuid, p_epoch uuid, p_primary uuid, p_token_store uuid, p_worker uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE a organization_witness.authorities%ROWTYPE; s organization_witness.slots%ROWTYPE;
BEGIN
    IF p_epoch IS NULL OR p_primary IS NULL OR p_token_store IS NULL OR p_worker IS NULL OR p_worker='00000000-0000-0000-0000-000000000000' THEN RAISE EXCEPTION 'invalid admission'; END IF;
    SELECT * INTO STRICT a FROM organization_witness.authorities WHERE environment_id=p_environment AND deployment_id=p_deployment FOR UPDATE;
    IF a.phase<>'active' OR a.epoch<>p_epoch OR a.primary_id<>p_primary OR a.token_store_id<>p_token_store THEN RAISE EXCEPTION 'inactive selection'; END IF;
    SELECT * INTO s FROM organization_witness.slots WHERE environment_id=p_environment AND worker_id=p_worker AND pending;
    -- An admission is an execution capability, not an idempotent command
    -- receipt. Returning it twice would let one owner release another's work.
    IF FOUND THEN RAISE EXCEPTION 'admission already pending'; END IF;
    SELECT * INTO STRICT s FROM organization_witness.slots WHERE environment_id=p_environment AND NOT pending AND generation<9223372036854775807 ORDER BY slot LIMIT 1;
    UPDATE organization_witness.slots SET generation=generation+1,pending=true,epoch=p_epoch,worker_id=p_worker,principal=session_user
        WHERE environment_id=p_environment AND slot=s.slot RETURNING * INTO s;
    RETURN to_jsonb(s);
END $function$

function:activate(p_environment uuid, p_.definition:
CREATE OR REPLACE FUNCTION organization_witness.activate(p_environment uuid, p_deployment uuid, p_operation uuid, p_expected bigint, p_acceptance text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE a organization_witness.authorities%ROWTYPE; old_from bigint;
BEGIN
    IF p_operation IS NULL OR p_expected IS NULL OR p_acceptance IS NULL THEN RAISE EXCEPTION 'invalid activation'; END IF;
    SELECT * INTO STRICT a FROM organization_witness.authorities WHERE environment_id=p_environment AND deployment_id=p_deployment FOR UPDATE;
    SELECT activate_from INTO STRICT old_from FROM organization_witness.operations WHERE environment_id=p_environment AND id=p_operation;
    IF a.operation_id=p_operation AND a.phase='active' AND old_from=p_expected AND a.acceptance_sha256=p_acceptance THEN
        RETURN organization_witness.current_state(p_environment,p_deployment);
    END IF;
    IF a.operation_id<>p_operation OR a.phase<>'prepared' OR a.revision<>p_expected OR a.revision>=9223372036854775806
       OR a.acceptance_sha256<>p_acceptance OR EXISTS(SELECT FROM organization_witness.slots WHERE environment_id=p_environment AND pending)
       THEN RAISE EXCEPTION 'activation boundary refused'; END IF;
    UPDATE organization_witness.operations SET activate_from=p_expected,activate_principal=session_user,activated_at=clock_timestamp() WHERE environment_id=p_environment AND id=p_operation;
    UPDATE organization_witness.authorities SET phase='active',revision=revision+1 WHERE environment_id=p_environment;
    RETURN organization_witness.current_state(p_environment,p_deployment);
END $function$

function:creation_finish(p_environment u.definition:
CREATE OR REPLACE FUNCTION organization_witness.creation_finish(p_environment uuid, p_deployment uuid, p_slot integer, p_generation bigint, p_epoch uuid, p_worker uuid, p_operation uuid, p_attempt integer, p_state text, p_receipt text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE a organization_witness.authorities%ROWTYPE; c organization_witness.creations%ROWTYPE;
BEGIN
 SELECT * INTO STRICT a FROM organization_witness.authorities WHERE environment_id=p_environment AND deployment_id=p_deployment FOR UPDATE;
 IF a.phase NOT IN ('active','fenced') OR a.epoch IS DISTINCT FROM p_epoch OR NOT EXISTS(
  SELECT FROM organization_witness.slots WHERE environment_id=p_environment AND slot=p_slot AND generation=p_generation
   AND epoch=p_epoch AND worker_id=p_worker AND principal=session_user AND pending)
 THEN RAISE EXCEPTION 'creation completion admission refused'; END IF;
 IF p_state IS NULL OR p_state NOT IN ('retryable','committed')
  OR (p_state='retryable' AND p_receipt IS NOT NULL)
  OR (p_state='committed' AND (p_receipt IS NULL OR NOT organization_witness.creation_digest(p_receipt)))
 THEN RAISE EXCEPTION 'creation outcome refused'; END IF;
 SELECT * INTO STRICT c FROM organization_witness.creations WHERE environment_id=p_environment AND operation_id=p_operation FOR UPDATE;
 IF ROW(c.epoch,c.slot,c.generation,c.worker_id,c.principal,c.attempt)
  IS DISTINCT FROM ROW(p_epoch,p_slot,p_generation,p_worker,session_user,p_attempt)
 THEN RAISE EXCEPTION 'creation attempt mismatch'; END IF;
 IF c.state=p_state AND c.receipt_sha256 IS NOT DISTINCT FROM p_receipt THEN RETURN to_jsonb(c); END IF;
 IF c.state<>'reserved' THEN RAISE EXCEPTION 'creation outcome immutable'; END IF;
 UPDATE organization_witness.creations SET state=p_state,receipt_sha256=p_receipt
  WHERE environment_id=p_environment AND operation_id=p_operation RETURNING * INTO c;
 PERFORM organization_witness.creation_event(p_environment,p_operation,false);
 RETURN to_jsonb(c);
END $function$

function:creation_lookup(p_environment u.definition:
CREATE OR REPLACE FUNCTION organization_witness.creation_lookup(p_environment uuid, p_deployment uuid, p_slot integer, p_generation bigint, p_epoch uuid, p_worker uuid, p_kind text, p_selector text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE c organization_witness.creations%ROWTYPE;
BEGIN
 PERFORM organization_witness.history_require_admission(p_environment,p_deployment,p_slot,p_generation,p_epoch,p_worker);
 IF p_kind IS NULL OR p_kind NOT IN ('management_create','management_invite','management_csv','registration','upstream')
  OR p_selector IS NULL OR NOT organization_witness.creation_digest(p_selector)
 THEN RAISE EXCEPTION 'creation lookup refused'; END IF;
 SELECT * INTO c FROM organization_witness.creations
  WHERE environment_id=p_environment AND kind=p_kind COLLATE "C" AND selector_sha256=p_selector COLLATE "C";
 IF NOT FOUND THEN RETURN 'null'::jsonb; END IF;
 RETURN to_jsonb(c);
END $function$

function:creation_prepare(p_environment.definition:
CREATE OR REPLACE FUNCTION organization_witness.creation_prepare(p_environment uuid, p_deployment uuid, p_slot integer, p_generation bigint, p_epoch uuid, p_worker uuid, p_kind text, p_selector text, p_actor text, p_payload text, p_subject text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE c organization_witness.creations%ROWTYPE; counts organization_witness.creation_counts%ROWTYPE; new_owner uuid;
BEGIN
 PERFORM organization_witness.history_require_admission(p_environment,p_deployment,p_slot,p_generation,p_epoch,p_worker);
 IF p_kind IS NULL OR p_kind NOT IN ('management_create','management_invite','management_csv','registration','upstream')
  OR p_selector IS NULL OR NOT organization_witness.creation_digest(p_selector)
  OR p_actor IS NULL OR NOT organization_witness.creation_digest(p_actor)
  OR p_payload IS NULL OR NOT organization_witness.creation_digest(p_payload)
  OR (p_subject IS NOT NULL AND NOT organization_witness.history_subject(p_subject))
 THEN RAISE EXCEPTION 'creation input refused'; END IF;
 SELECT * INTO c FROM organization_witness.creations
  WHERE environment_id=p_environment AND kind=p_kind COLLATE "C" AND selector_sha256=p_selector COLLATE "C" FOR UPDATE;
 IF FOUND THEN
  IF c.actor_sha256 IS DISTINCT FROM p_actor OR c.payload_sha256 IS DISTINCT FROM p_payload
   OR c.requested_subject IS DISTINCT FROM p_subject COLLATE "C"
  THEN RAISE EXCEPTION 'creation conflict'; END IF;
  IF c.state='committed' THEN RETURN to_jsonb(c); END IF;
  IF c.epoch IS DISTINCT FROM p_epoch THEN RAISE EXCEPTION 'creation requires epoch reconciliation'; END IF;
  IF c.state='reserved' THEN
   IF ROW(c.slot,c.generation,c.worker_id,c.principal) IS DISTINCT FROM ROW(p_slot,p_generation,p_worker,session_user)
   THEN RAISE EXCEPTION 'creation attempt still reserved'; END IF;
   RETURN to_jsonb(c);
  END IF;
  IF c.attempt>=32 THEN RAISE EXCEPTION 'creation attempts exhausted'; END IF;
 ELSE
  INSERT INTO organization_witness.creation_counts(environment_id) VALUES(p_environment) ON CONFLICT DO NOTHING;
 END IF;
 SELECT * INTO STRICT counts FROM organization_witness.creation_counts WHERE environment_id=p_environment FOR UPDATE;
 IF counts.events::bigint+counts.reserved+2>1000000 THEN RAISE EXCEPTION 'creation event capacity exhausted'; END IF;
 IF c.operation_id IS NULL THEN
  IF counts.operations>=500000 THEN RAISE EXCEPTION 'creation capacity exhausted'; END IF;
  new_owner := gen_random_uuid();
  PERFORM organization_witness.history_reserve(p_environment,p_deployment,p_slot,p_generation,p_epoch,p_worker,new_owner,COALESCE(p_subject,new_owner::text));
  INSERT INTO organization_witness.creations(environment_id,operation_id,kind,selector_sha256,actor_sha256,payload_sha256,requested_subject,
   owner_id,subject,state,attempt,epoch,slot,generation,worker_id,principal)
  VALUES(p_environment,gen_random_uuid(),p_kind,p_selector,p_actor,p_payload,p_subject,new_owner,COALESCE(p_subject,new_owner::text),
   'reserved',1,p_epoch,p_slot,p_generation,p_worker,session_user) RETURNING * INTO c;
  UPDATE organization_witness.creation_counts SET operations=operations+1 WHERE environment_id=p_environment;
 ELSE
  UPDATE organization_witness.creations SET state='reserved',attempt=attempt+1,slot=p_slot,generation=p_generation,worker_id=p_worker,principal=session_user
   WHERE environment_id=p_environment AND operation_id=c.operation_id RETURNING * INTO c;
 END IF;
 PERFORM organization_witness.creation_event(p_environment,c.operation_id,true);
 RETURN to_jsonb(c);
END $function$

function:current_state(p_environment uui.definition:
CREATE OR REPLACE FUNCTION organization_witness.current_state(p_environment uuid, p_deployment uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE a organization_witness.authorities%ROWTYPE; n integer;
BEGIN
    SELECT * INTO STRICT a FROM organization_witness.authorities WHERE environment_id=p_environment AND deployment_id=p_deployment FOR SHARE;
    SELECT count(*) INTO n FROM organization_witness.slots WHERE environment_id=p_environment AND pending;
    RETURN to_jsonb(a) || jsonb_build_object('pending',n);
END $function$

function:deployment_acquire(p_deployment.definition:
CREATE OR REPLACE FUNCTION organization_witness.deployment_acquire(p_deployment uuid, p_epoch uuid, p_primary uuid, p_token uuid, p_worker uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE d organization_witness.deployments%ROWTYPE; s organization_witness.deployment_slots%ROWTYPE;
BEGIN
 IF p_epoch IS NULL OR p_primary IS NULL OR p_token IS NULL OR p_worker IS NULL OR p_worker='00000000-0000-0000-0000-000000000000' THEN RAISE EXCEPTION 'invalid deployment admission'; END IF;
 SELECT * INTO STRICT d FROM organization_witness.deployments WHERE deployment_id=p_deployment FOR UPDATE;
 IF d.phase<>'active' OR ROW(d.epoch,d.primary_id,d.token_store_id) IS DISTINCT FROM ROW(p_epoch,p_primary,p_token) THEN RAISE EXCEPTION 'inactive deployment selection'; END IF;
 IF NOT EXISTS(SELECT FROM organization_witness.deployment_store_checkpoints WHERE deployment_id=p_deployment AND epoch=p_epoch AND primary_id=p_primary AND token_store_id=p_token) THEN RAISE EXCEPTION 'deployment store checkpoint required'; END IF;
 IF EXISTS(SELECT FROM organization_witness.deployment_slots WHERE deployment_id=p_deployment AND worker_id=p_worker AND pending) THEN RAISE EXCEPTION 'deployment admission already pending'; END IF;
 SELECT * INTO STRICT s FROM organization_witness.deployment_slots WHERE deployment_id=p_deployment AND NOT pending AND generation<9223372036854775807 ORDER BY slot LIMIT 1;
 UPDATE organization_witness.deployment_slots SET generation=generation+1,pending=true,epoch=p_epoch,worker_id=p_worker,principal=session_user WHERE deployment_id=p_deployment AND slot=s.slot RETURNING * INTO s;
 RETURN to_jsonb(s);
END $function$

function:deployment_acquire_child(p_depl.definition:
CREATE OR REPLACE FUNCTION organization_witness.deployment_acquire_child(p_deployment uuid, p_parent_slot integer, p_parent_generation bigint, p_parent_epoch uuid, p_parent_worker uuid, p_environment uuid, p_child_epoch uuid, p_primary uuid, p_token uuid, p_child_worker uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE d organization_witness.deployments%ROWTYPE; s organization_witness.deployment_slots%ROWTYPE; child jsonb;
BEGIN
 SELECT * INTO STRICT d FROM organization_witness.deployments WHERE deployment_id=p_deployment FOR UPDATE;
 SELECT * INTO STRICT s FROM organization_witness.deployment_slots WHERE deployment_id=p_deployment AND slot=p_parent_slot FOR UPDATE;
 IF d.phase<>'active' OR NOT s.pending OR ROW(s.generation,s.epoch,s.worker_id,s.principal) IS DISTINCT FROM ROW(p_parent_generation,p_parent_epoch,p_parent_worker,session_user)
 OR d.epoch IS DISTINCT FROM p_parent_epoch OR ROW(d.primary_id,d.token_store_id) IS DISTINCT FROM ROW(p_primary,p_token)
 OR NOT EXISTS(SELECT FROM organization_witness.deployment_children WHERE environment_id=p_environment AND child_epoch=p_child_epoch AND deployment_id=p_deployment AND deployment_epoch=p_parent_epoch)
 THEN RAISE EXCEPTION 'deployment parent admission refused'; END IF;
 child := organization_witness.acquire(p_environment,p_deployment,p_child_epoch,p_primary,p_token,p_child_worker);
 INSERT INTO organization_witness.deployment_child_slots VALUES(p_environment,(child->>'slot')::integer,(child->>'generation')::bigint,p_deployment,p_parent_slot,p_parent_generation)
 ON CONFLICT(environment_id,child_slot) DO UPDATE SET child_generation=excluded.child_generation,deployment_id=excluded.deployment_id,parent_slot=excluded.parent_slot,parent_generation=excluded.parent_generation;
 RETURN child;
END $function$

function:deployment_activate(p_deploymen.definition:
CREATE OR REPLACE FUNCTION organization_witness.deployment_activate(p_deployment uuid, p_operation uuid, p_expected bigint, p_acceptance text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE d organization_witness.deployments%ROWTYPE; old_from bigint;
BEGIN
 IF p_operation IS NULL OR p_expected IS NULL OR p_acceptance IS NULL THEN RAISE EXCEPTION 'invalid deployment activation'; END IF;
 SELECT * INTO STRICT d FROM organization_witness.deployments WHERE deployment_id=p_deployment FOR UPDATE;
 IF EXISTS(SELECT FROM organization_witness.maintenance_slots WHERE deployment_id=p_deployment AND pending) THEN RAISE EXCEPTION 'maintenance still pending'; END IF;
 SELECT activate_from INTO STRICT old_from FROM organization_witness.deployment_operations WHERE deployment_id=p_deployment AND operation_id=p_operation;
 IF d.operation_id=p_operation AND d.phase='active' AND old_from=p_expected AND d.acceptance_sha256=p_acceptance
 THEN RETURN organization_witness.deployment_state(p_deployment); END IF;
 IF d.operation_id<>p_operation OR d.phase<>'prepared' OR d.revision<>p_expected OR d.revision>=9223372036854775806 OR d.acceptance_sha256<>p_acceptance
 OR EXISTS(SELECT FROM organization_witness.deployment_slots WHERE deployment_id=p_deployment AND pending)
 THEN RAISE EXCEPTION 'deployment activation boundary refused'; END IF;
 IF NOT EXISTS(SELECT FROM organization_witness.deployment_store_checkpoints WHERE deployment_id=p_deployment AND epoch=d.epoch AND operation_id=p_operation AND prepared_revision=p_expected AND primary_id=d.primary_id AND token_store_id=d.token_store_id) THEN RAISE EXCEPTION 'deployment store checkpoint required'; END IF;
 UPDATE organization_witness.deployment_operations SET activate_from=p_expected,activate_principal=session_user,activated_at=clock_timestamp() WHERE deployment_id=p_deployment AND operation_id=p_operation;
 UPDATE organization_witness.deployments SET phase='active',revision=revision+1 WHERE deployment_id=p_deployment;
 RETURN organization_witness.deployment_state(p_deployment);
END $function$

function:deployment_bind_child(p_deploym.definition:
CREATE OR REPLACE FUNCTION organization_witness.deployment_bind_child(p_deployment uuid, p_epoch uuid, p_environment uuid, p_child_epoch uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE d organization_witness.deployments%ROWTYPE; a organization_witness.authorities%ROWTYPE;
BEGIN
 SELECT * INTO STRICT d FROM organization_witness.deployments WHERE deployment_id=p_deployment FOR UPDATE;
 SELECT * INTO STRICT a FROM organization_witness.authorities WHERE environment_id=p_environment AND deployment_id=p_deployment FOR UPDATE;
 IF p_epoch IS NULL OR p_child_epoch IS NULL OR d.phase<>'active' OR d.epoch<>p_epoch OR a.phase<>'prepared' OR a.epoch<>p_child_epoch
 OR ROW(a.primary_id,a.token_store_id) IS DISTINCT FROM ROW(d.primary_id,d.token_store_id)
 THEN RAISE EXCEPTION 'deployment child selection refused'; END IF;
 INSERT INTO organization_witness.deployment_children(environment_id,child_epoch,deployment_id,deployment_epoch) VALUES(p_environment,p_child_epoch,p_deployment,p_epoch) ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT FROM organization_witness.deployment_children WHERE environment_id=p_environment AND child_epoch=p_child_epoch AND deployment_id=p_deployment AND deployment_epoch=p_epoch)
 THEN RAISE EXCEPTION 'deployment child epoch already bound'; END IF;
END $function$

function:deployment_fence(p_deployment u.definition:
CREATE OR REPLACE FUNCTION organization_witness.deployment_fence(p_deployment uuid, p_operation uuid, p_expected bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE d organization_witness.deployments%ROWTYPE; old_from bigint; terminal boolean;
BEGIN
 IF p_operation IS NULL OR p_operation='00000000-0000-0000-0000-000000000000' THEN RAISE EXCEPTION 'invalid operation'; END IF;
 SELECT * INTO STRICT d FROM organization_witness.deployments WHERE deployment_id=p_deployment FOR UPDATE;
 SELECT fence_from INTO old_from FROM organization_witness.deployment_operations WHERE deployment_id=p_deployment AND operation_id=p_operation;
 IF FOUND THEN
  IF d.operation_id=p_operation AND d.phase='fenced' AND old_from=p_expected THEN RETURN organization_witness.deployment_state(p_deployment); END IF;
  RAISE EXCEPTION 'conflicting deployment fence replay';
 END IF;
 IF p_expected IS NULL OR d.revision<>p_expected OR d.revision=9223372036854775807 THEN RAISE EXCEPTION 'deployment fence revision refused'; END IF;
 terminal := (SELECT count(*) FROM organization_witness.deployment_operations WHERE deployment_id=p_deployment)>=65536;
 INSERT INTO organization_witness.deployment_operations(deployment_id,operation_id,fence_from) VALUES(p_deployment,p_operation,p_expected);
 UPDATE organization_witness.deployments SET phase='fenced',operation_id=p_operation,revision=CASE WHEN terminal THEN 9223372036854775807 ELSE revision+1 END WHERE deployment_id=p_deployment;
 RETURN organization_witness.deployment_state(p_deployment);
END $function$

function:deployment_initialize(p_deploym.definition:
CREATE OR REPLACE FUNCTION organization_witness.deployment_initialize(p_deployment uuid, p_operation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
BEGIN
 LOCK TABLE organization_witness.deployments IN SHARE ROW EXCLUSIVE MODE;
 IF EXISTS(SELECT FROM organization_witness.authorities WHERE deployment_id IS DISTINCT FROM p_deployment)
 THEN RAISE EXCEPTION 'deployment conflicts with existing child ownership'; END IF;
 INSERT INTO organization_witness.deployments(deployment_id,revision,phase,operation_id) VALUES(p_deployment,1,'fenced',p_operation);
 INSERT INTO organization_witness.deployment_operations(deployment_id,operation_id,fence_from) VALUES(p_deployment,p_operation,0);
 INSERT INTO organization_witness.deployment_slots(deployment_id,slot) SELECT p_deployment,n FROM generate_series(0,63) n;
 RETURN organization_witness.deployment_state(p_deployment);
END $function$

function:deployment_pending_work(p_deplo.definition:
CREATE OR REPLACE FUNCTION organization_witness.deployment_pending_work(p_deployment uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE d organization_witness.deployments%ROWTYPE; admissions jsonb;
BEGIN
 SELECT * INTO STRICT d FROM organization_witness.deployments WHERE deployment_id=p_deployment FOR SHARE;
 SELECT COALESCE(jsonb_agg(to_jsonb(s) ORDER BY s.slot),'[]'::jsonb) INTO admissions
 FROM organization_witness.deployment_slots s WHERE s.deployment_id=p_deployment AND s.pending;
 RETURN jsonb_build_object('state',to_jsonb(d)||jsonb_build_object('pending',jsonb_array_length(admissions)), 'admissions',admissions);
END $function$

function:deployment_prepare(p_deployment.definition:
CREATE OR REPLACE FUNCTION organization_witness.deployment_prepare(p_deployment uuid, p_operation uuid, p_expected bigint, p_epoch uuid, p_primary uuid, p_token uuid, p_source text, p_history text, p_acceptance text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE d organization_witness.deployments%ROWTYPE; old_from bigint;
BEGIN
 IF p_operation IS NULL OR p_expected IS NULL OR p_epoch IS NULL OR p_primary IS NULL OR p_token IS NULL
 OR p_epoch='00000000-0000-0000-0000-000000000000' OR p_primary='00000000-0000-0000-0000-000000000000' OR p_token='00000000-0000-0000-0000-000000000000'
 OR NOT organization_witness.creation_digest(p_source) OR NOT organization_witness.creation_digest(p_history) OR NOT organization_witness.creation_digest(p_acceptance)
 THEN RAISE EXCEPTION 'invalid deployment preparation'; END IF;
 SELECT * INTO STRICT d FROM organization_witness.deployments WHERE deployment_id=p_deployment FOR UPDATE;
 IF EXISTS(SELECT FROM organization_witness.maintenance_slots WHERE deployment_id=p_deployment AND pending) THEN RAISE EXCEPTION 'maintenance still pending'; END IF;
 SELECT prepare_from INTO STRICT old_from FROM organization_witness.deployment_operations WHERE deployment_id=p_deployment AND operation_id=p_operation;
 IF d.operation_id=p_operation AND d.phase='prepared' AND old_from=p_expected
 AND ROW(d.epoch,d.primary_id,d.token_store_id,d.source_sha256,d.history_sha256,d.acceptance_sha256)
  IS NOT DISTINCT FROM ROW(p_epoch,p_primary,p_token,p_source,p_history,p_acceptance)
 THEN RETURN organization_witness.deployment_state(p_deployment); END IF;
 IF d.operation_id<>p_operation OR d.phase<>'fenced' OR d.revision<>p_expected OR d.revision>=9223372036854775806
 OR EXISTS(SELECT FROM organization_witness.deployment_slots WHERE deployment_id=p_deployment AND pending)
 OR EXISTS(SELECT FROM organization_witness.authorities WHERE deployment_id=p_deployment AND phase<>'fenced')
 OR EXISTS(SELECT FROM organization_witness.slots s JOIN organization_witness.authorities a USING(environment_id) WHERE a.deployment_id=p_deployment AND s.pending)
 THEN RAISE EXCEPTION 'deployment preparation boundary refused'; END IF;
 INSERT INTO organization_witness.deployment_epochs(deployment_id,epoch,operation_id) VALUES(p_deployment,p_epoch,p_operation);
 UPDATE organization_witness.deployment_operations SET prepare_from=p_expected,prepare_principal=session_user,prepared_at=clock_timestamp() WHERE deployment_id=p_deployment AND operation_id=p_operation;
 UPDATE organization_witness.deployments SET phase='prepared',revision=revision+1,epoch=p_epoch,primary_id=p_primary,token_store_id=p_token,
 source_sha256=p_source,history_sha256=p_history,acceptance_sha256=p_acceptance WHERE deployment_id=p_deployment;
 RETURN organization_witness.deployment_state(p_deployment);
END $function$

function:deployment_release(p_deployment.definition:
CREATE OR REPLACE FUNCTION organization_witness.deployment_release(p_deployment uuid, p_slot integer, p_generation bigint, p_epoch uuid, p_worker uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE s organization_witness.deployment_slots%ROWTYPE;
BEGIN
 PERFORM 1 FROM organization_witness.deployments WHERE deployment_id=p_deployment FOR UPDATE;
 SELECT * INTO STRICT s FROM organization_witness.deployment_slots WHERE deployment_id=p_deployment AND slot=p_slot FOR UPDATE;
 IF p_generation IS NULL OR p_generation<=0 OR ROW(s.generation,s.epoch,s.worker_id,s.principal) IS DISTINCT FROM ROW(p_generation,p_epoch,p_worker,session_user)
 THEN RAISE EXCEPTION 'deployment completion refused'; END IF;
 IF EXISTS(SELECT FROM organization_witness.deployment_child_slots c JOIN organization_witness.slots child_slot
  ON child_slot.environment_id=c.environment_id AND child_slot.slot=c.child_slot AND child_slot.generation=c.child_generation AND child_slot.pending
  WHERE c.deployment_id=p_deployment AND c.parent_slot=p_slot AND c.parent_generation=p_generation)
 THEN RAISE EXCEPTION 'deployment child still pending'; END IF;
 IF EXISTS(SELECT FROM organization_witness.deployment_store_observations WHERE deployment_id=p_deployment AND slot=p_slot AND generation=p_generation AND finished_wal IS NULL) THEN RAISE EXCEPTION 'deployment store observation unfinished'; END IF;
 UPDATE organization_witness.deployment_slots SET pending=false WHERE deployment_id=p_deployment AND slot=p_slot;
 RETURN organization_witness.deployment_state(p_deployment);
END $function$

