function:deployment_store_progress_begin.definition:
CREATE OR REPLACE FUNCTION organization_witness.deployment_store_progress_begin(p_deployment uuid, p_slot integer, p_generation bigint, p_epoch uuid, p_worker uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE a organization_witness.deployments%ROWTYPE; c organization_witness.deployment_store_checkpoints%ROWTYPE; o organization_witness.deployment_store_observations%ROWTYPE;
BEGIN
 SELECT * INTO STRICT a FROM organization_witness.deployments WHERE deployment_id=p_deployment FOR UPDATE;
 IF a.phase<>'active' OR a.epoch IS DISTINCT FROM p_epoch OR NOT EXISTS(
  SELECT FROM organization_witness.deployment_slots WHERE deployment_id=p_deployment AND slot=p_slot AND generation=p_generation
   AND epoch=p_epoch AND worker_id=p_worker AND principal=session_user AND pending)
 THEN RAISE EXCEPTION 'store observation admission refused'; END IF;
 SELECT * INTO STRICT c FROM organization_witness.deployment_store_checkpoints WHERE deployment_id=p_deployment AND epoch=p_epoch;
 IF c.primary_id IS DISTINCT FROM a.primary_id OR c.token_store_id IS DISTINCT FROM a.token_store_id
  OR EXISTS(SELECT FROM organization_witness.deployment_store_observations WHERE deployment_id=p_deployment AND slot=p_slot AND generation=p_generation)
 THEN RAISE EXCEPTION 'store observation already begun or selection differs'; END IF;
 INSERT INTO organization_witness.deployment_store_observations VALUES(p_deployment,p_slot,p_generation,p_epoch,p_worker,session_user,c.wal_position,NULL)
 ON CONFLICT(deployment_id,slot) DO UPDATE SET generation=EXCLUDED.generation,epoch=EXCLUDED.epoch,
  worker_id=EXCLUDED.worker_id,principal=EXCLUDED.principal,minimum_wal=EXCLUDED.minimum_wal,finished_wal=NULL RETURNING * INTO o;
 RETURN jsonb_build_object('checkpoint',to_jsonb(c),'observation',to_jsonb(o));
END $function$

function:deployment_store_progress_finis.definition:
CREATE OR REPLACE FUNCTION organization_witness.deployment_store_progress_finish(p_deployment uuid, p_slot integer, p_generation bigint, p_epoch uuid, p_worker uuid, p_primary jsonb, p_token jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE a organization_witness.deployments%ROWTYPE; c organization_witness.deployment_store_checkpoints%ROWTYPE; o organization_witness.deployment_store_observations%ROWTYPE; position numeric;
BEGIN
 IF NOT organization_witness.store_observation_valid(p_primary,p_token) THEN RAISE EXCEPTION 'invalid store observation'; END IF;
 SELECT * INTO STRICT a FROM organization_witness.deployments WHERE deployment_id=p_deployment FOR UPDATE;
 IF a.phase NOT IN ('active','fenced') OR a.epoch IS DISTINCT FROM p_epoch OR NOT EXISTS(
  SELECT FROM organization_witness.deployment_slots WHERE deployment_id=p_deployment AND slot=p_slot AND generation=p_generation
   AND epoch=p_epoch AND worker_id=p_worker AND principal=session_user AND pending)
 THEN RAISE EXCEPTION 'store observation completion refused'; END IF;
 SELECT * INTO STRICT c FROM organization_witness.deployment_store_checkpoints WHERE deployment_id=p_deployment AND epoch=p_epoch;
 SELECT * INTO STRICT o FROM organization_witness.deployment_store_observations WHERE deployment_id=p_deployment AND slot=p_slot
  AND generation=p_generation AND epoch=p_epoch AND worker_id=p_worker AND principal=session_user;
 position:=(p_primary->>'wal_position')::numeric;
 IF c.primary_id IS DISTINCT FROM a.primary_id OR c.token_store_id IS DISTINCT FROM a.token_store_id
  OR c.primary_incarnation IS DISTINCT FROM p_primary-'wal_position' OR c.token_incarnation IS DISTINCT FROM p_token
  OR position<o.minimum_wal OR (o.finished_wal IS NOT NULL AND o.finished_wal IS DISTINCT FROM position)
 THEN RAISE EXCEPTION 'store progress differs or regressed'; END IF;
 UPDATE organization_witness.deployment_store_checkpoints SET wal_position=greatest(wal_position,position)
  WHERE deployment_id=p_deployment AND epoch=p_epoch RETURNING * INTO c;
 UPDATE organization_witness.deployment_store_observations SET finished_wal=position WHERE deployment_id=p_deployment AND slot=p_slot;
 RETURN jsonb_build_object('checkpoint',to_jsonb(c),'observation',to_jsonb(o)||jsonb_build_object('finished_wal',position));
END $function$

function:deployment_store_progress_pin(p.definition:
CREATE OR REPLACE FUNCTION organization_witness.deployment_store_progress_pin(p_deployment uuid, p_operation uuid, p_revision bigint, p_primary jsonb, p_token jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE a organization_witness.deployments%ROWTYPE; c organization_witness.deployment_store_checkpoints%ROWTYPE; position numeric;
BEGIN
 IF NOT organization_witness.store_observation_valid(p_primary,p_token) THEN RAISE EXCEPTION 'invalid store observation'; END IF;
 SELECT * INTO STRICT a FROM organization_witness.deployments WHERE deployment_id=p_deployment FOR UPDATE;
 IF a.phase<>'prepared' OR a.operation_id IS DISTINCT FROM p_operation OR a.revision IS DISTINCT FROM p_revision
  OR EXISTS(SELECT FROM organization_witness.deployment_slots WHERE deployment_id=p_deployment AND pending)
 THEN RAISE EXCEPTION 'store pin requires exact drained preparation'; END IF;
 position:=(p_primary->>'wal_position')::numeric;
 SELECT * INTO c FROM organization_witness.deployment_store_checkpoints WHERE deployment_id=p_deployment AND epoch=a.epoch;
 IF FOUND THEN
  IF c.operation_id IS DISTINCT FROM p_operation OR c.prepared_revision IS DISTINCT FROM p_revision
   OR c.primary_id IS DISTINCT FROM a.primary_id OR c.token_store_id IS DISTINCT FROM a.token_store_id
   OR c.primary_incarnation IS DISTINCT FROM p_primary-'wal_position' OR c.token_incarnation IS DISTINCT FROM p_token
   OR position<c.initial_wal
  THEN RAISE EXCEPTION 'store pin replay conflicts'; END IF;
  RETURN to_jsonb(c);
 END IF;
 INSERT INTO organization_witness.deployment_store_checkpoints VALUES(p_deployment,a.epoch,p_operation,p_revision,
  a.primary_id,a.token_store_id,p_primary-'wal_position',p_token,position,position,session_user) RETURNING * INTO c;
 RETURN to_jsonb(c);
END $function$

function:fence(p_environment uuid, p_dep.definition:
CREATE OR REPLACE FUNCTION organization_witness.fence(p_environment uuid, p_deployment uuid, p_operation uuid, p_expected bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE a organization_witness.authorities%ROWTYPE; old_from bigint; terminal boolean;
BEGIN
    IF p_operation IS NULL OR p_operation='00000000-0000-0000-0000-000000000000' THEN RAISE EXCEPTION 'invalid operation'; END IF;
    SELECT * INTO STRICT a FROM organization_witness.authorities WHERE environment_id=p_environment AND deployment_id=p_deployment FOR UPDATE;
    SELECT fence_from INTO old_from FROM organization_witness.operations WHERE environment_id=p_environment AND id=p_operation;
    IF FOUND THEN
        IF a.operation_id=p_operation AND a.phase='fenced' AND old_from=p_expected THEN
            RETURN organization_witness.current_state(p_environment,p_deployment);
        END IF;
        RAISE EXCEPTION 'conflicting fence replay';
    END IF;
    IF p_expected IS NULL OR a.revision<>p_expected OR a.revision=9223372036854775807 THEN RAISE EXCEPTION 'fence revision refused'; END IF;
    terminal := (SELECT count(*) FROM organization_witness.operations WHERE environment_id=p_environment)>=65536;
    INSERT INTO organization_witness.operations(environment_id,id,fence_from) VALUES(p_environment,p_operation,p_expected);
    UPDATE organization_witness.authorities SET phase='fenced',revision=CASE WHEN terminal THEN 9223372036854775807 ELSE revision+1 END,operation_id=p_operation WHERE environment_id=p_environment;
    RETURN organization_witness.current_state(p_environment,p_deployment);
END $function$

function:history_append(p_environment uu.definition:
CREATE OR REPLACE FUNCTION organization_witness.history_append(p_environment uuid, p_kind smallint, p_owner uuid, p_subject text, p_epoch uuid, p_worker uuid, p_slot integer, p_generation bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE h organization_witness.history_namespaces%ROWTYPE; next_digest bytea; next_sequence bigint; operation_uuid uuid;
BEGIN
 SELECT * INTO STRICT h FROM organization_witness.history_namespaces WHERE environment_id=p_environment FOR UPDATE;
 IF h.sequence>=1000000 THEN RAISE EXCEPTION 'history capacity exhausted'; END IF;
 IF p_kind=0 THEN
  INSERT INTO organization_witness.history_owners(owner_id,environment_id) VALUES(p_owner,p_environment);
 END IF;
 next_sequence := h.sequence+1;
 next_digest := sha256(h.digest||int8send(next_sequence)||decode(lpad(to_hex(p_kind::integer),2,'0'),'hex')||uuid_send(p_owner)
  ||int4send(octet_length(COALESCE(p_subject,'')))||convert_to(COALESCE(p_subject,''),'UTF8'));
 operation_uuid := CASE WHEN p_epoch IS NULL THEN h.operation_id ELSE (SELECT operation_id FROM organization_witness.authorities WHERE environment_id=p_environment) END;
 INSERT INTO organization_witness.history_entries(environment_id,sequence,kind,owner_id,subject,operation_id,epoch,worker_id,slot,generation,previous_digest,digest)
 VALUES(p_environment,next_sequence,p_kind,p_owner,p_subject,operation_uuid,p_epoch,p_worker,p_slot,p_generation,h.digest,next_digest);
 UPDATE organization_witness.history_namespaces SET sequence=next_sequence,digest=next_digest,
  owner_count=owner_count+CASE WHEN p_kind=0 THEN 1 ELSE 0 END,
  subject_count=subject_count+CASE WHEN p_kind=1 THEN 1 ELSE 0 END WHERE environment_id=p_environment;
END $function$

function:history_batch(p_environment uui.definition:
CREATE OR REPLACE FUNCTION organization_witness.history_batch(p_environment uuid, p_deployment uuid, p_operation uuid, p_revision bigint, p_from bigint, p_entries jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE h organization_witness.history_namespaces%ROWTYPE; old_entry organization_witness.history_entries%ROWTYPE;
 item jsonb; owner_uuid uuid; subject_value text; entry_kind smallint; position bigint; n integer; prior_owner uuid; prior_subject text;
BEGIN
 PERFORM organization_witness.history_require_fence(p_environment,p_deployment,p_operation,p_revision);
 SELECT * INTO STRICT h FROM organization_witness.history_namespaces WHERE environment_id=p_environment FOR UPDATE;
 IF h.operation_id IS DISTINCT FROM p_operation OR h.control_revision IS DISTINCT FROM p_revision
  OR p_from IS NULL OR p_from<0 OR p_from>h.sequence OR p_entries IS NULL
  OR jsonb_typeof(p_entries)<>'array' OR octet_length(p_entries::text)>1048576
 THEN RAISE EXCEPTION 'invalid history batch'; END IF;
 n := jsonb_array_length(p_entries);
 IF n<1 OR n>256 OR p_from+n>1000000 OR (p_from<h.sequence AND p_from+n>h.sequence)
  OR (h.sealed AND p_from+n>h.sequence) THEN RAISE EXCEPTION 'history batch range refused'; END IF;
 position := p_from;
 FOR item IN SELECT value FROM jsonb_array_elements(p_entries) LOOP
  position := position+1;
  IF jsonb_typeof(item)<>'object' OR item-ARRAY['kind','owner_id','subject']<>'{}'::jsonb
   OR NOT (item ?& ARRAY['kind','owner_id','subject']) OR jsonb_typeof(item->'owner_id')<>'string'
   OR item->>'kind' NOT IN ('owner','reservation') OR item->>'kind' IS NULL
  THEN RAISE EXCEPTION 'invalid history entry'; END IF;
  owner_uuid := (item->>'owner_id')::uuid;
  IF owner_uuid::text IS DISTINCT FROM item->>'owner_id' THEN RAISE EXCEPTION 'noncanonical owner input'; END IF;
  entry_kind := CASE WHEN item->>'kind'='owner' THEN 0 ELSE 1 END;
  subject_value := item->>'subject';
  IF (entry_kind=0 AND item->'subject'<>'null'::jsonb) OR
   (entry_kind=1 AND (jsonb_typeof(item->'subject')<>'string' OR NOT organization_witness.history_subject(subject_value)))
  THEN RAISE EXCEPTION 'invalid history subject'; END IF;
  IF position<=h.sequence THEN
   SELECT * INTO STRICT old_entry FROM organization_witness.history_entries WHERE environment_id=p_environment AND sequence=position;
   IF ROW(old_entry.kind,old_entry.owner_id,old_entry.subject) IS DISTINCT FROM ROW(entry_kind,owner_uuid,subject_value)
   THEN RAISE EXCEPTION 'conflicting history replay'; END IF;
  ELSE
   IF entry_kind=0 THEN
    IF h.subject_count<>0 OR h.owner_count>=h.expected_owners THEN RAISE EXCEPTION 'history owner order refused'; END IF;
    SELECT owner_id INTO prior_owner FROM organization_witness.history_entries WHERE environment_id=p_environment AND kind=0 ORDER BY sequence DESC LIMIT 1;
    IF prior_owner IS NOT NULL AND owner_uuid<=prior_owner THEN RAISE EXCEPTION 'history owner order refused'; END IF;
   ELSE
    IF h.owner_count<>h.expected_owners OR h.subject_count>=h.expected_subjects THEN RAISE EXCEPTION 'history subject order refused'; END IF;
    SELECT subject INTO prior_subject FROM organization_witness.history_entries WHERE environment_id=p_environment AND kind=1 ORDER BY sequence DESC LIMIT 1;
    IF prior_subject IS NOT NULL AND subject_value COLLATE "C"<=prior_subject COLLATE "C" THEN RAISE EXCEPTION 'history subject order refused'; END IF;
   END IF;
   PERFORM organization_witness.history_append(p_environment,entry_kind,owner_uuid,subject_value,NULL,NULL,NULL,NULL);
   SELECT * INTO STRICT h FROM organization_witness.history_namespaces WHERE environment_id=p_environment;
  END IF;
 END LOOP;
 RETURN organization_witness.history_progress(p_environment);
END $function$

function:history_begin(p_environment uui.definition:
CREATE OR REPLACE FUNCTION organization_witness.history_begin(p_environment uuid, p_deployment uuid, p_operation uuid, p_revision bigint, p_issuer text, p_receipt uuid, p_manifest text, p_inventory text, p_owners integer, p_subjects integer, p_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE h organization_witness.history_namespaces%ROWTYPE; initial bytea;
BEGIN
 PERFORM organization_witness.history_require_fence(p_environment,p_deployment,p_operation,p_revision);
 SELECT * INTO h FROM organization_witness.history_namespaces WHERE environment_id=p_environment FOR UPDATE;
 IF FOUND THEN
  IF ROW(h.operation_id,h.control_revision,h.issuer_host,h.receipt_id,h.manifest_sha256,h.inventory_sha256,h.expected_owners,h.expected_subjects,h.expected_digest)
   IS DISTINCT FROM ROW(p_operation,p_revision,p_issuer,p_receipt,p_manifest,p_inventory,p_owners,p_subjects,p_digest)
  THEN RAISE EXCEPTION 'conflicting history enrollment'; END IF;
  RETURN organization_witness.history_progress(p_environment);
 END IF;
 initial := sha256(convert_to('aegaeon-permanent-history-v1','UTF8')||decode('00','hex')||uuid_send(p_environment)||int4send(octet_length(p_issuer))||convert_to(p_issuer,'UTF8'));
 INSERT INTO organization_witness.history_namespaces(environment_id,issuer_host,operation_id,control_revision,receipt_id,
  manifest_sha256,inventory_sha256,expected_owners,expected_subjects,expected_digest,digest)
 VALUES(p_environment,p_issuer,p_operation,p_revision,p_receipt,p_manifest,p_inventory,p_owners,p_subjects,p_digest,initial);
 RETURN organization_witness.history_progress(p_environment);
END $function$

function:history_read(p_environment uuid.definition:
CREATE OR REPLACE FUNCTION organization_witness.history_read(p_environment uuid, p_deployment uuid, p_operation uuid, p_revision bigint, p_after bigint, p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE h organization_witness.history_namespaces%ROWTYPE; entries jsonb;
BEGIN
 PERFORM organization_witness.history_require_fence(p_environment,p_deployment,p_operation,p_revision);
 SELECT * INTO STRICT h FROM organization_witness.history_namespaces WHERE environment_id=p_environment FOR SHARE;
 IF p_after IS NULL OR p_after<0 OR p_after>h.sequence OR p_limit IS NULL OR p_limit<1 OR p_limit>256
 THEN RAISE EXCEPTION 'history inspection range refused'; END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('sequence',e.sequence,'kind',CASE WHEN e.kind=0 THEN 'owner' ELSE 'reservation' END,
  'owner_id',e.owner_id,'subject',e.subject,'operation_id',e.operation_id,'epoch',e.epoch,'worker_id',e.worker_id,'slot',e.slot,'generation',e.generation,'principal',e.principal,'recorded_at',e.recorded_at,'previous_digest',encode(e.previous_digest,'hex'),'digest',encode(e.digest,'hex')) ORDER BY e.sequence),'[]'::jsonb) INTO entries
 FROM (SELECT * FROM organization_witness.history_entries WHERE environment_id=p_environment AND sequence>p_after ORDER BY sequence LIMIT p_limit) e;
 RETURN jsonb_build_object('progress',organization_witness.history_progress(p_environment),'entries',entries);
END $function$

function:history_reserve(p_environment u.definition:
CREATE OR REPLACE FUNCTION organization_witness.history_reserve(p_environment uuid, p_deployment uuid, p_slot integer, p_generation bigint, p_epoch uuid, p_worker uuid, p_owner uuid, p_subject text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE existing_environment uuid; existing_owner uuid;
BEGIN
 PERFORM organization_witness.history_require_admission(p_environment,p_deployment,p_slot,p_generation,p_epoch,p_worker);
 IF p_owner IS NULL OR p_subject IS NULL OR NOT organization_witness.history_subject(p_subject) THEN RAISE EXCEPTION 'history reservation refused'; END IF;
 SELECT environment_id INTO existing_environment FROM organization_witness.history_owners WHERE owner_id=p_owner;
 IF FOUND THEN
  IF existing_environment<>p_environment THEN RAISE EXCEPTION 'permanent owner conflict'; END IF;
 ELSE
  PERFORM organization_witness.history_append(p_environment,0::smallint,p_owner,NULL,p_epoch,p_worker,p_slot,p_generation);
 END IF;
 SELECT owner_id INTO existing_owner FROM organization_witness.history_entries WHERE environment_id=p_environment AND kind=1 AND subject=p_subject COLLATE "C";
 IF FOUND THEN
  IF existing_owner<>p_owner THEN RAISE EXCEPTION 'permanent subject conflict'; END IF;
 ELSE
  PERFORM organization_witness.history_append(p_environment,1::smallint,p_owner,p_subject,p_epoch,p_worker,p_slot,p_generation);
 END IF;
 RETURN organization_witness.history_progress(p_environment);
END $function$

function:history_seal(p_environment uuid.definition:
CREATE OR REPLACE FUNCTION organization_witness.history_seal(p_environment uuid, p_deployment uuid, p_operation uuid, p_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE h organization_witness.history_namespaces%ROWTYPE;
BEGIN
 PERFORM organization_witness.history_require_fence(p_environment,p_deployment,p_operation,p_revision);
 SELECT * INTO STRICT h FROM organization_witness.history_namespaces WHERE environment_id=p_environment FOR UPDATE;
 IF h.operation_id IS DISTINCT FROM p_operation OR h.control_revision IS DISTINCT FROM p_revision
  OR h.owner_count<>h.expected_owners OR h.subject_count<>h.expected_subjects OR encode(h.digest,'hex')<>h.expected_digest
 THEN RAISE EXCEPTION 'history sealing refused'; END IF;
 UPDATE organization_witness.history_namespaces SET sealed=true WHERE environment_id=p_environment;
 RETURN organization_witness.history_progress(p_environment);
END $function$

function:initialize(p_environment uuid,.definition:
CREATE OR REPLACE FUNCTION organization_witness.initialize(p_environment uuid, p_deployment uuid, p_operation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
BEGIN
    -- Creation is explicit and never changes an existing authority. Its lost reply
    -- is reconciled through current_state, not an idempotent reinitialization.
    PERFORM 1 FROM organization_witness.deployments WHERE deployment_id=p_deployment FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'matching deployment registration required'; END IF;
    LOCK TABLE organization_witness.authorities IN SHARE ROW EXCLUSIVE MODE;
    IF (SELECT count(*) FROM organization_witness.authorities)>=1024 THEN RAISE EXCEPTION 'environment capacity exhausted'; END IF;
    INSERT INTO organization_witness.authorities(environment_id,deployment_id,revision,phase,operation_id)
        VALUES(p_environment,p_deployment,1,'fenced',p_operation);
    INSERT INTO organization_witness.operations(environment_id,id,fence_from) VALUES(p_environment,p_operation,0);
    INSERT INTO organization_witness.slots(environment_id,slot) SELECT p_environment,n FROM generate_series(0,63) n;
    RETURN organization_witness.current_state(p_environment,p_deployment);
END $function$

function:maintenance_acquire(p_deploymen.definition:
CREATE OR REPLACE FUNCTION organization_witness.maintenance_acquire(p_deployment uuid, p_fence uuid, p_revision bigint, p_work uuid, p_kind text, p_plan text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE d organization_witness.deployments%ROWTYPE; s organization_witness.maintenance_slots%ROWTYPE;
BEGIN
 IF p_fence IS NULL OR p_fence='00000000-0000-0000-0000-000000000000'
 OR p_work IS NULL OR p_work='00000000-0000-0000-0000-000000000000'
 OR p_revision IS NULL OR p_revision<=0 OR p_kind IS NULL OR p_plan IS NULL
 THEN RAISE EXCEPTION 'explicit maintenance plan and fence required'; END IF;
 SELECT * INTO STRICT d FROM organization_witness.deployments WHERE deployment_id=p_deployment FOR UPDATE;
 IF d.phase<>'fenced' OR d.operation_id<>p_fence OR d.revision<>p_revision
 OR EXISTS(SELECT FROM organization_witness.deployment_slots WHERE deployment_id=p_deployment AND pending)
 THEN RAISE EXCEPTION 'drained deployment fence required'; END IF;
 PERFORM 1 FROM organization_witness.authorities WHERE deployment_id=p_deployment ORDER BY environment_id FOR UPDATE;
 IF EXISTS(SELECT FROM organization_witness.authorities WHERE deployment_id=p_deployment AND phase<>'fenced')
 OR EXISTS(SELECT FROM organization_witness.slots child_slot JOIN organization_witness.authorities child_authority USING(environment_id)
   WHERE child_authority.deployment_id=p_deployment AND child_slot.pending)
 THEN RAISE EXCEPTION 'drained child fences required'; END IF;
 INSERT INTO organization_witness.maintenance_slots(deployment_id) VALUES(p_deployment) ON CONFLICT DO NOTHING;
 SELECT * INTO STRICT s FROM organization_witness.maintenance_slots WHERE deployment_id=p_deployment FOR UPDATE;
 IF s.pending OR s.generation>=9223372036854775807 THEN RAISE EXCEPTION 'maintenance unavailable'; END IF;
 UPDATE organization_witness.maintenance_slots SET generation=generation+1,pending=true,
   fence_operation_id=p_fence,fence_revision=p_revision,work_id=p_work,principal=session_user,
   kind=p_kind,plan_sha256=p_plan,completion_sha256=NULL WHERE deployment_id=p_deployment RETURNING * INTO s;
 RETURN to_jsonb(s);
END $function$

function:maintenance_complete(p_deployme.definition:
CREATE OR REPLACE FUNCTION organization_witness.maintenance_complete(p_deployment uuid, p_generation bigint, p_work uuid, p_plan text, p_completion text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE s organization_witness.maintenance_slots%ROWTYPE;
BEGIN
 PERFORM 1 FROM organization_witness.deployments WHERE deployment_id=p_deployment FOR UPDATE;
 SELECT * INTO STRICT s FROM organization_witness.maintenance_slots WHERE deployment_id=p_deployment FOR UPDATE;
 IF ROW(s.generation,s.work_id,s.plan_sha256,s.principal) IS DISTINCT FROM ROW(p_generation,p_work,p_plan,session_user)
 OR p_completion IS NULL OR p_completion !~ '^[0-9a-f]{64}$'
 THEN RAISE EXCEPTION 'maintenance completion differs'; END IF;
 IF NOT s.pending THEN
   IF s.completion_sha256=p_completion THEN RETURN to_jsonb(s); END IF;
   RAISE EXCEPTION 'maintenance completion conflicts';
 END IF;
 UPDATE organization_witness.maintenance_slots SET pending=false,completion_sha256=p_completion
   WHERE deployment_id=p_deployment RETURNING * INTO s;
 RETURN to_jsonb(s);
END $function$

function:maintenance_state(p_deployment.definition:
CREATE OR REPLACE FUNCTION organization_witness.maintenance_state(p_deployment uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE s organization_witness.maintenance_slots%ROWTYPE;
BEGIN
 PERFORM 1 FROM organization_witness.deployments WHERE deployment_id=p_deployment;
 IF NOT FOUND THEN RAISE EXCEPTION 'deployment missing'; END IF;
 SELECT * INTO s FROM organization_witness.maintenance_slots WHERE deployment_id=p_deployment;
 IF NOT FOUND THEN RETURN jsonb_build_object('deployment_id',p_deployment,'generation',0,'pending',false); END IF;
 RETURN to_jsonb(s);
END $function$

function:prepare(p_environment uuid, p_d.definition:
CREATE OR REPLACE FUNCTION organization_witness.prepare(p_environment uuid, p_deployment uuid, p_operation uuid, p_expected bigint, p_epoch uuid, p_primary uuid, p_token_store uuid, p_source text, p_history text, p_acceptance text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE a organization_witness.authorities%ROWTYPE; old_from bigint;
BEGIN
    IF p_epoch IS NULL OR p_primary IS NULL OR p_token_store IS NULL
       OR p_epoch='00000000-0000-0000-0000-000000000000' OR p_primary='00000000-0000-0000-0000-000000000000' OR p_token_store='00000000-0000-0000-0000-000000000000'
       OR p_source IS NULL OR p_history IS NULL OR p_acceptance IS NULL
       OR p_source COLLATE "C" !~ '^[0-9a-f]{64}$' OR p_history COLLATE "C" !~ '^[0-9a-f]{64}$' OR p_acceptance COLLATE "C" !~ '^[0-9a-f]{64}$'
       OR p_operation IS NULL OR p_expected IS NULL THEN RAISE EXCEPTION 'invalid preparation'; END IF;
    SELECT * INTO STRICT a FROM organization_witness.authorities WHERE environment_id=p_environment AND deployment_id=p_deployment FOR UPDATE;
    SELECT prepare_from INTO STRICT old_from FROM organization_witness.operations WHERE environment_id=p_environment AND id=p_operation;
    IF a.operation_id=p_operation AND a.phase='prepared' AND old_from=p_expected
       AND a.epoch=p_epoch AND a.primary_id=p_primary AND a.token_store_id=p_token_store
       AND a.source_sha256=p_source AND a.history_sha256=p_history AND a.acceptance_sha256=p_acceptance THEN
        RETURN organization_witness.current_state(p_environment,p_deployment);
    END IF;
    IF a.operation_id<>p_operation OR a.phase<>'fenced' OR a.revision<>p_expected OR a.revision>=9223372036854775806
       OR EXISTS(SELECT FROM organization_witness.slots WHERE environment_id=p_environment AND pending) THEN RAISE EXCEPTION 'preparation boundary refused'; END IF;
    INSERT INTO organization_witness.epochs(environment_id,epoch,operation_id) VALUES(p_environment,p_epoch,p_operation);
    UPDATE organization_witness.operations SET prepare_from=p_expected,prepare_principal=session_user,prepared_at=clock_timestamp() WHERE environment_id=p_environment AND id=p_operation;
    UPDATE organization_witness.authorities SET phase='prepared',revision=revision+1,epoch=p_epoch,primary_id=p_primary,token_store_id=p_token_store,
        source_sha256=p_source,history_sha256=p_history,acceptance_sha256=p_acceptance WHERE environment_id=p_environment;
    RETURN organization_witness.current_state(p_environment,p_deployment);
END $function$

function:release(p_environment uuid, p_d.definition:
CREATE OR REPLACE FUNCTION organization_witness.release(p_environment uuid, p_deployment uuid, p_slot integer, p_generation bigint, p_epoch uuid, p_worker uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE a organization_witness.authorities%ROWTYPE; s organization_witness.slots%ROWTYPE;
BEGIN
 SELECT * INTO STRICT a FROM organization_witness.authorities WHERE environment_id=p_environment AND deployment_id=p_deployment FOR UPDATE;
 SELECT * INTO STRICT s FROM organization_witness.slots WHERE environment_id=p_environment AND slot=p_slot;
 IF p_generation IS NULL OR p_epoch IS NULL OR p_worker IS NULL OR p_generation<=0
  OR s.generation<>p_generation OR s.epoch IS DISTINCT FROM p_epoch OR s.worker_id IS DISTINCT FROM p_worker OR s.principal IS DISTINCT FROM session_user
 THEN RAISE EXCEPTION 'admission completion refused'; END IF;
 IF EXISTS(SELECT FROM organization_witness.creations WHERE environment_id=p_environment AND epoch=p_epoch AND slot=p_slot
  AND generation=p_generation AND worker_id=p_worker AND state='reserved')
 THEN RAISE EXCEPTION 'creation attempt still reserved'; END IF;
 UPDATE organization_witness.slots SET pending=false WHERE environment_id=p_environment AND slot=p_slot;
 RETURN organization_witness.current_state(p_environment,p_deployment);
END $function$

function:store_progress_begin(p_environm.definition:
CREATE OR REPLACE FUNCTION organization_witness.store_progress_begin(p_environment uuid, p_deployment uuid, p_slot integer, p_generation bigint, p_epoch uuid, p_worker uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE a organization_witness.authorities%ROWTYPE; c organization_witness.store_checkpoints%ROWTYPE; o organization_witness.store_observations%ROWTYPE;
BEGIN
 SELECT * INTO STRICT a FROM organization_witness.authorities WHERE environment_id=p_environment AND deployment_id=p_deployment FOR UPDATE;
 IF a.phase<>'active' OR a.epoch IS DISTINCT FROM p_epoch OR NOT EXISTS(
  SELECT FROM organization_witness.slots WHERE environment_id=p_environment AND slot=p_slot AND generation=p_generation
   AND epoch=p_epoch AND worker_id=p_worker AND principal=session_user AND pending)
 THEN RAISE EXCEPTION 'store observation admission refused'; END IF;
 SELECT * INTO STRICT c FROM organization_witness.store_checkpoints WHERE environment_id=p_environment AND epoch=p_epoch;
 IF c.primary_id IS DISTINCT FROM a.primary_id OR c.token_store_id IS DISTINCT FROM a.token_store_id
  OR EXISTS(SELECT FROM organization_witness.store_observations WHERE environment_id=p_environment AND slot=p_slot AND generation=p_generation)
 THEN RAISE EXCEPTION 'store observation already begun or selection differs'; END IF;
 INSERT INTO organization_witness.store_observations VALUES(p_environment,p_slot,p_generation,p_epoch,p_worker,session_user,c.wal_position,NULL)
 ON CONFLICT(environment_id,slot) DO UPDATE SET generation=EXCLUDED.generation,epoch=EXCLUDED.epoch,
  worker_id=EXCLUDED.worker_id,principal=EXCLUDED.principal,minimum_wal=EXCLUDED.minimum_wal,finished_wal=NULL RETURNING * INTO o;
 RETURN jsonb_build_object('checkpoint',to_jsonb(c),'observation',to_jsonb(o));
END $function$

function:store_progress_finish(p_environ.definition:
CREATE OR REPLACE FUNCTION organization_witness.store_progress_finish(p_environment uuid, p_deployment uuid, p_slot integer, p_generation bigint, p_epoch uuid, p_worker uuid, p_primary jsonb, p_token jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE a organization_witness.authorities%ROWTYPE; c organization_witness.store_checkpoints%ROWTYPE; o organization_witness.store_observations%ROWTYPE; position numeric;
BEGIN
 IF NOT organization_witness.store_observation_valid(p_primary,p_token) THEN RAISE EXCEPTION 'invalid store observation'; END IF;
 SELECT * INTO STRICT a FROM organization_witness.authorities WHERE environment_id=p_environment AND deployment_id=p_deployment FOR UPDATE;
 IF a.phase NOT IN ('active','fenced') OR a.epoch IS DISTINCT FROM p_epoch OR NOT EXISTS(
  SELECT FROM organization_witness.slots WHERE environment_id=p_environment AND slot=p_slot AND generation=p_generation
   AND epoch=p_epoch AND worker_id=p_worker AND principal=session_user AND pending)
 THEN RAISE EXCEPTION 'store observation completion refused'; END IF;
 SELECT * INTO STRICT c FROM organization_witness.store_checkpoints WHERE environment_id=p_environment AND epoch=p_epoch;
 SELECT * INTO STRICT o FROM organization_witness.store_observations WHERE environment_id=p_environment AND slot=p_slot
  AND generation=p_generation AND epoch=p_epoch AND worker_id=p_worker AND principal=session_user;
 position:=(p_primary->>'wal_position')::numeric;
 IF c.primary_id IS DISTINCT FROM a.primary_id OR c.token_store_id IS DISTINCT FROM a.token_store_id
  OR c.primary_incarnation IS DISTINCT FROM p_primary-'wal_position' OR c.token_incarnation IS DISTINCT FROM p_token
  OR position<o.minimum_wal OR (o.finished_wal IS NOT NULL AND o.finished_wal IS DISTINCT FROM position)
 THEN RAISE EXCEPTION 'store progress differs or regressed'; END IF;
 UPDATE organization_witness.store_checkpoints SET wal_position=greatest(wal_position,position)
  WHERE environment_id=p_environment AND epoch=p_epoch RETURNING * INTO c;
 UPDATE organization_witness.store_observations SET finished_wal=position WHERE environment_id=p_environment AND slot=p_slot;
 RETURN jsonb_build_object('checkpoint',to_jsonb(c),'observation',to_jsonb(o)||jsonb_build_object('finished_wal',position));
END $function$

function:store_progress_pin(p_environmen.definition:
CREATE OR REPLACE FUNCTION organization_witness.store_progress_pin(p_environment uuid, p_deployment uuid, p_operation uuid, p_revision bigint, p_primary jsonb, p_token jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'organization_witness'
AS $function$
DECLARE a organization_witness.authorities%ROWTYPE; c organization_witness.store_checkpoints%ROWTYPE; position numeric;
BEGIN
 IF NOT organization_witness.store_observation_valid(p_primary,p_token) THEN RAISE EXCEPTION 'invalid store observation'; END IF;
 SELECT * INTO STRICT a FROM organization_witness.authorities WHERE environment_id=p_environment AND deployment_id=p_deployment FOR UPDATE;
 IF a.phase<>'prepared' OR a.operation_id IS DISTINCT FROM p_operation OR a.revision IS DISTINCT FROM p_revision
  OR EXISTS(SELECT FROM organization_witness.slots WHERE environment_id=p_environment AND pending)
 THEN RAISE EXCEPTION 'store pin requires exact drained preparation'; END IF;
 position:=(p_primary->>'wal_position')::numeric;
 SELECT * INTO c FROM organization_witness.store_checkpoints WHERE environment_id=p_environment AND epoch=a.epoch;
 IF FOUND THEN
  IF c.operation_id IS DISTINCT FROM p_operation OR c.prepared_revision IS DISTINCT FROM p_revision
   OR c.primary_id IS DISTINCT FROM a.primary_id OR c.token_store_id IS DISTINCT FROM a.token_store_id
   OR c.primary_incarnation IS DISTINCT FROM p_primary-'wal_position' OR c.token_incarnation IS DISTINCT FROM p_token
   OR position<c.initial_wal
  THEN RAISE EXCEPTION 'store pin replay conflicts'; END IF;
  RETURN to_jsonb(c);
 END IF;
 INSERT INTO organization_witness.store_checkpoints VALUES(p_environment,a.epoch,p_operation,p_revision,
  a.primary_id,a.token_store_id,p_primary-'wal_position',p_token,position,position,session_user) RETURNING * INTO c;
 RETURN to_jsonb(c);
END $function$
